def cache(fn):
    memo={}
    def wrapper(*a):
        if a not in memo:memo[a]=fn(*a)
        return memo[a]
    return wrapper
@cache
def fib(n):return n if n<2 else fib(n-1)+fib(n-2)
print(fib(30))

def fibonacci(n):
    a,b=0,1
    for _ in range(n):
        yield a
        a,b=b,a+b
print(list(fibonacci(10)))

def repeat(n):
    def decorator(fn):
        def wrapper(*a):
            for _ in range(n):fn(*a)
        return wrapper
    return decorator
@repeat(3)
def say(msg):print(msg)
say('你好')

class CountCalls:
    def __init__(s,fn):s.fn=fn;s.count=0
    def __call__(s,*a):
        s.count+=1
        print(f'第{s.count}次调用')
        return s.fn(*a)
@CountCalls
def hello():print('hello')
hello();hello();hello()
